"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Plus, Edit, Trash2, Loader2, Check, X } from "lucide-react"
import { toast } from "sonner"

export default function CountriesManagementPage() {
  const router = useRouter()
  const [countries, setCountries] = useState([])
  const [loading, setLoading] = useState(true)
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingCountry, setEditingCountry] = useState(null)
  const [formData, setFormData] = useState({
    name: "",
    code: "",
    region: "",
    active: true,
    supported: true,
    flag: "",
  })

  useEffect(() => {
    const token = localStorage.getItem("token")
    if (!token) {
      router.push("/admin/login")
      return
    }
    fetchCountries()
  }, [router])

  async function fetchCountries() {
    try {
      const token = localStorage.getItem("token")
      const response = await fetch("/api/v1/admin/country", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
      const data = await response.json()
      if (data.success) {
        setCountries(data.countries)
      }
    } catch (error) {
      toast.error("Failed to fetch countries")
    } finally {
      setLoading(false)
    }
  }

  async function handleSubmit(e) {
    e.preventDefault()

    try {
      const token = localStorage.getItem("token")
      const url = editingCountry ? "/api/v1/admin/country" : "/api/v1/admin/country"
      const method = editingCountry ? "PUT" : "POST"

      const payload = editingCountry ? { ...formData, id: editingCountry._id } : formData

      const response = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      })

      const data = await response.json()

      if (data.success) {
        toast.success(data.message)
        setDialogOpen(false)
        resetForm()
        fetchCountries()
      } else {
        toast.error(data.error || "Operation failed")
      }
    } catch (error) {
      toast.error("An error occurred")
    }
  }

  async function handleDelete(id) {
    if (!confirm("Are you sure you want to delete this country?")) return

    try {
      const token = localStorage.getItem("token")
      const response = await fetch(`/api/v1/admin/country?id=${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })

      const data = await response.json()

      if (data.success) {
        toast.success(data.message)
        fetchCountries()
      } else {
        toast.error(data.error || "Delete failed")
      }
    } catch (error) {
      toast.error("An error occurred")
    }
  }

  function openEditDialog(country) {
    setEditingCountry(country)
    setFormData({
      name: country.name,
      code: country.code,
      region: country.region,
      active: country.active,
      supported: country.supported,
      flag: country.flag || "",
    })
    setDialogOpen(true)
  }

  function resetForm() {
    setEditingCountry(null)
    setFormData({
      name: "",
      code: "",
      region: "",
      active: true,
      supported: true,
      flag: "",
    })
  }

  const regions = ["North America", "South America", "Europe", "Asia", "Africa", "Middle East", "Oceania"]

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-emerald-600" />
      </div>
    )
  }

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-4xl font-bold mb-2">Countries Management</h1>
          <p className="text-muted-foreground">Manage available countries for eSIM plans</p>
        </div>
        <Dialog
          open={dialogOpen}
          onOpenChange={(open) => {
            setDialogOpen(open)
            if (!open) resetForm()
          }}
        >
          <DialogTrigger asChild>
            <Button className="bg-gradient-to-r from-emerald-600 to-blue-600">
              <Plus className="h-4 w-4 mr-2" />
              Add Country
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{editingCountry ? "Edit Country" : "Add New Country"}</DialogTitle>
              <DialogDescription>
                {editingCountry ? "Update country information" : "Add a new country to the platform"}
              </DialogDescription>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="name">Country Name *</Label>
                <Input
                  id="name"
                  required
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g. United States"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="code">Country Code (ISO 2) *</Label>
                <Input
                  id="code"
                  required
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
                  placeholder="e.g. US"
                  maxLength={2}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="region">Region *</Label>
                <Select value={formData.region} onValueChange={(value) => setFormData({ ...formData, region: value })}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select region" />
                  </SelectTrigger>
                  <SelectContent>
                    {regions.map((region) => (
                      <SelectItem key={region} value={region}>
                        {region}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="flag">Flag Emoji (optional)</Label>
                <Input
                  id="flag"
                  value={formData.flag}
                  onChange={(e) => setFormData({ ...formData, flag: e.target.value })}
                  placeholder="🇺🇸"
                />
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.active}
                    onChange={(e) => setFormData({ ...formData, active: e.target.checked })}
                    className="h-4 w-4"
                  />
                  <span className="text-sm">Active</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.supported}
                    onChange={(e) => setFormData({ ...formData, supported: e.target.checked })}
                    className="h-4 w-4"
                  />
                  <span className="text-sm">Supported</span>
                </label>
              </div>
              <DialogFooter>
                <Button type="submit" className="bg-gradient-to-r from-emerald-600 to-blue-600">
                  {editingCountry ? "Update Country" : "Add Country"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>All Countries ({countries.length})</CardTitle>
          <CardDescription>View and manage all countries in the system</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b">
                  <th className="text-left py-3 px-4 font-medium">Country</th>
                  <th className="text-left py-3 px-4 font-medium">Code</th>
                  <th className="text-left py-3 px-4 font-medium">Region</th>
                  <th className="text-left py-3 px-4 font-medium">Status</th>
                  <th className="text-right py-3 px-4 font-medium">Actions</th>
                </tr>
              </thead>
              <tbody>
                {countries.map((country) => (
                  <tr key={country._id} className="border-b hover:bg-secondary/50">
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-2">
                        <span className="text-2xl">{country.flag || "🌍"}</span>
                        <span className="font-medium">{country.name}</span>
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <Badge variant="outline">{country.code}</Badge>
                    </td>
                    <td className="py-3 px-4 text-sm text-muted-foreground">{country.region}</td>
                    <td className="py-3 px-4">
                      <div className="flex gap-2">
                        {country.active ? (
                          <Badge className="gap-1 bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-300">
                            <Check className="h-3 w-3" />
                            Active
                          </Badge>
                        ) : (
                          <Badge variant="secondary" className="gap-1">
                            <X className="h-3 w-3" />
                            Inactive
                          </Badge>
                        )}
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="flex items-center justify-end gap-2">
                        <Button variant="ghost" size="icon" onClick={() => openEditDialog(country)}>
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button variant="ghost" size="icon" onClick={() => handleDelete(country._id)}>
                          <Trash2 className="h-4 w-4 text-red-600" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}
